        shayariItem(767, "जब तुम अचानक मेरा नाम लेकर मुस्कुराते हो,\nसच्ची, उस पल दिल में तितलियाँ उड़ने लगती हैं।", "_ शायरी", cat, "तितलियाँ"),
        shayariItem(768, "मौसम कोई भी हो बाहर, दिल में तो सावन ही रहता है,\nजब तक तेरा प्यार भरा साथ मेरे पास रहता है।", "_ शायरी", cat, "सावन"),
        shayariItem(769, "तुमसे मिलने के बाद ही पता चला कि प्यार क्या होता है,\nवरना पहले तो ये शब्द सिर्फ़ किताबों में अच्छा लगता था।", "_ शायरी", cat, "किताब"),
        shayariItem(770, "तेरी आँखों की गहराई में डूबने का डर नहीं मुझे,\nक्योंकि तैरने से ज़्यादा मज़ा तेरे प्यार में डूबने में है।", "_ शायरी", cat, "गहराई"),
        shayariItem(771, "चाँदनी रात में छत पर टहलते हुए जब तेरा फोन आता है,\nतो ऐसा लगता है जैसे तारे भी मुस्कुराने लगे हों।", "_ शायरी", cat, "चाँदनी रात"),
        shayariItem(772, "हर रोज़ नई तस्वीर सी लगती है तेरी मुस्कान,\nजितनी बार देखूँ उतनी बार नया प्यार हो जाता है।", "_ शायरी", cat, "तस्वीर"),
        shayariItem(773, "मैं लफ़्ज़ हूँ तो तुम उसका पूरा मतलब हो,\nमैं रास्ता हूँ तो तुम मेरी सबसे प्यारी मंज़िल हो।", "_ शायरी", cat, "मंज़िल"),
        shayariItem(774, "तेरा हाथ जब मेरे हाथ में होता है,\nतो ज़िंदगी की हर मुश्किल बहुत छोटी लगती है।", "_ शायरी", cat, "भरोसा"),
        shayariItem(775, "मेरे दिल के हर कोने में तेरी तस्वीर सजी है,\nतेरे बिना ये दुनिया मुझे बड़ी बेरंग लगती है।", "_ शायरी", cat, "तस्वीर"),
        shayariItem(776, "कभी-कभी सिर्फ़ तुम्हें गले लगाकर रो लेने का मन करता है,\nबिना किसी वजह के बस तेरी बाहों में सुकून लेने का मन करता है।", "_ शायरी", cat, "सुकून"),
        shayariItem(777, "तुम्हारी पायल की झंकार आज भी कानों में गूँजती है,\nजैसे तुम हर पल मेरे आस-पास ही घूमती हो।", "_ शायरी", cat, "पायल"),
        shayariItem(778, "दुनिया की कोई भी दौलत मेरी नज़र में कुछ नहीं,\nजब तक तेरा प्यार भरा दिल मेरे पास है।", "_ शायरी", cat, "दौलत"),
        shayariItem(779, "तेरे साथ बिताया हर एक संडे किसी जश्न से कम नहीं,\nसुबह की चाय से लेकर रात की बातों तक सब खास होता है।", "_ शायरी", cat, "साथ"),
        shayariItem(780, "मेरा हर गीत तेरे नाम से शुरू होता है,\nऔर तेरी मुस्कान पर आकर पूरा होता है।", "_ शायरी", cat, "गीत"),
        shayariItem(781, "जिस दिन तुमसे बात न हो वो दिन अधूरा सा लगता है,\nतुम्हारी एक हेलो से पूरा दिन खिल उठता है।", "_ शायरी", cat, "बातचीत"),
        shayariItem(782, "तुम्हारी सादगी ने ही तो मुझे दीवाना बनाया है,\nवरना सजावटों की दुनिया में कौन दिल हारता है।", "_ शायरी", cat, "सादगी"),
        shayariItem(783, "रब से जब भी कुछ माँगा तो बस तुम्हारा साथ माँगा,\nहर खुशी से पहले तेरी सलामती का हाथ माँगा।", "_ शायरी", cat, "दुआ"),
        shayariItem(784, "तेरे होठों की मुस्कान मेरी सबसे बड़ी कमज़ोरी है,\nइसे बनाए रखने के लिए मैं पूरी दुनिया से लड़ सकता हूँ।", "_ शायरी", cat, "मुस्कान"),
        shayariItem(785, "मेरी सुबह की पहली सोच और रात का आख़िरी ख़याल हो तुम,\nमेरी हर अनकही कहानी का सबसे सुंदर सवाल हो तुम।", "_ शायरी", cat, "ख़याल"),
        shayariItem(786, "चलो आज फिर से हाथ पकड़कर वादा करते हैं,\nउम्र चाहे जितनी बढ़ जाए प्यार हमेशा जवाँ रखेंगे।", "_ शायरी", cat, "वादा"),
        shayariItem(787, "तेरी हँसी की खनक मेरे घर को मंदिर बना देती है,\nतेरी मौजूदगी मेरी हर कमी को पूरा कर देती है।", "_ शायरी", cat, "घर"),
        shayariItem(788, "नज़दीकियाँ जब रूह से जुड़ती हैं तो वक़्त नहीं देखतीं,\nबस एक-दूसरे की धड़कन में अपनी दुनिया देखती हैं।", "_ शायरी", cat, "रूह"),
        shayariItem(789, "बिन बोले भी मेरी सारी बातें समझ लेते हो तुम,\nशायद इसलिए इस दिल के सबसे करीब रहते हो तुम।", "_ शायरी", cat, "समझ"),
        shayariItem(790, "तुम्हारे संग हर लंबी ड्राइव छोटी पड़ जाती है,\nपसंदीदा गाने और तुम्हारी बातें सफ़र को यादगार बना देती हैं।", "_ शायरी", cat, "सफ़र"),
        shayariItem(791, "फूलों की क्या ज़रूरत जब तुम खुद बहार हो,\nमेरी सूनी ज़िंदगी का तुम ही तो इकलौता प्यार हो।", "_ शायरी", cat, "बहार"),
        shayariItem(792, "जब तुम मेरी तरफ़ देखकर पलकें झुकाते हो,\nसौ दफ़ा मर जाता हूँ मैं उस एक अदा पर।", "_ शायरी", cat, "अदा"),
        shayariItem(793, "दिल की हर गली में अब सिर्फ़ तेरा ही शोर है,\nतू ही मेरा सवेरा है और तू ही मेरी भोर है।", "_ शायरी", cat, "सवेरा"),
        shayariItem(794, "हवा भी आज तेरी ख़ुशबू लेकर आई है,\nलगता है तूने आज फिर दिल से मुझे याद किया है।", "_ शायरी", cat, "याद"),
        shayariItem(795, "हम दोनों की कहानी बिल्कुल किसी फ़िल्म जैसी लगती है,\nथोड़ी नोकझोंक, थोड़ा गुस्सा और ढेर सारा प्यार।", "_ शायरी", cat, "कहानी"),
        shayariItem(796, "तुम्हारा हाथ मेरे सिर पर हो तो नींद भी मीठी आती है,\nसारे बुरे ख़्वाब दूर हो जाते हैं बस तेरी खुशबू रह जाती है।", "_ शायरी", cat, "नींद"),
        shayariItem(797, "हर किसी को नहीं मिलता ऐसा सच्चा हमदर्द,\nशुक्र है खुदा का कि उसने तुझे मेरी किस्मत में लिखा।", "_ शायरी", cat, "किस्मत"),
        shayariItem(798, "तेरे साथ हर मुश्किल सफ़र भी पिकनिक सा लगता है,\nतेरी हँसी हर दर्द को पल भर में भुला देती है।", "_ शायरी", cat, "हँसी"),
        shayariItem(799, "बस यूँ ही साथ चलते रहना हाथ थामे हुए,\nदुनिया बदल जाए पर हमारा ये प्यार न बदले कभी।", "_ शायरी", cat, "हमेशा"),
        shayariItem(800, "तू मिले तो हर दिन वैलेंटाइन जैसा लगता है,\nतेरे बिना तो सावन भी रेगिस्तान जैसा लगता है।", "_ शायरी", cat, "प्यार")
    )
}
